import simd

/// Full description of a "universe" — the only thing a saved location stores (§7a, §7e).
struct EnvironmentConfig: Codable, Equatable {
    var seed: UInt64
    var generatorVersion: Int = 1          // §7e migration guard

    // Nebula (L2)
    enum NebulaBackend: String, Codable { case splat, particles }
    // Splats jitter (reprojection shift+bounce) as a full-surround volume on the vOS27
    // beta — ruled out distance, projection mode, splat size, and sort order. Shipping
    // particles until Apple fixes surround-splat reprojection (FB filed). SplatNebula
    // stays implemented behind the protocol for when it does (§10).
    var nebulaBackend: NebulaBackend = .particles
    var nebulaPalette: Int = 0
    var nebulaDensity: Float = 0.6

    // Stars (L3)
    var starDensity: Float = 1.0
    var starColorMix: Float = 0.5

    // Backdrop (L1)
    var backdrop: Int = 0

    // Phenomena rates (L4, §6)
    var cometRate: Float = 0.1
    var meteorRate: Float = 0.4

    // Optional hero content
    var body: BodyConfig? = nil                    // §7c
    var asteroidField: AsteroidFieldConfig? = nil  // §7d

    static func random(seed: UInt64) -> EnvironmentConfig {
        var rng = SeededRandom(seed: seed)
        var c = EnvironmentConfig(seed: seed)
        c.nebulaPalette = Int(rng.next() % 8)
        // Pick over the ACTUAL panorama count, not % 8 — the old modulus double-weighted
        // backdrops 0 and 1 (6→0, 7→1), which is why jumps kept landing on the same skies.
        c.backdrop = Int(rng.next() % UInt64(FarBackdrop.textureNames.count))
        // §7a: suppress generated nebula against a busy real sky (see FarBackdrop.busyness).
        c.nebulaDensity = rng.unit() * FarBackdrop.nebulaScale(forBackdrop: c.backdrop)
        // TODO: roll body / asteroidField per §7a variety policy (open decision §11 #7).
        return c
    }
}

/// §7c hero body.
struct BodyConfig: Codable, Equatable {
    enum Kind: String, Codable { case proceduralPlanet, namedBody, star }
    var kind: Kind = .proceduralPlanet
    var named: String? = nil                 // e.g. "Saturn" for the Sol System preset
    var hasRings: Bool = false
    var ringsResolveClose: Bool = true       // §7c two-tier rings
    var atmosphereTint: SIMD3<Float> = [0.4, 0.6, 1.0]
    var distance: Float = 90                 // §3 hero distance ~40–150 m
}

/// §7d asteroid field.
struct AsteroidFieldConfig: Codable, Equatable {
    var count: Int = 300
    var safetyRadius: Float = 2.5            // §7d/§9 exclusion bubble — never violated
    var enableImpacts: Bool = true          // §7d emergent layer (free-running)
    var tameRocksForFlicking: Int = 3       // §7f reachable rocks (open decision §11 #14)
}

import SwiftUI
import RealityKit

/// App-wide observable state: immersion status + the currently active universe.
/// Spec: §7a (EnvironmentConfig drives everything), §5 (one clock), §7e (saved places).
@Observable
@MainActor
final class AppModel {
    static let immersiveSpaceID = "FloatSpace"

    enum ImmersionState { case closed, opening, open }
    var immersion: ImmersionState = .closed

    /// Which environment is currently shown. `importedSpatial` = the bundled Apple Spatial
    /// stereo image; `generated` = our procedural L1–L4 scene. Toggled for A/B comparison.
    enum EnvironmentSource { case importedSpatial, generated }
    var environmentSource: EnvironmentSource = .importedSpatial   // launch into the imported image

    /// Which bundled Apple Spatial sky is showing (index into SpatialImageEnvironment.resourceNames).
    var importedIndex: Int = 0

    /// The config that fully describes the current universe (§7a).
    var currentConfig: EnvironmentConfig = .random(seed: 0x0F10A7)

    /// Global animation clock (§5). Shared by every animated system.
    let clock = AnimationClock()

    /// Saved "Places" (§7e).
    var savedLocations: [SavedLocation] = []

    /// Persistent container holding the active universe root(s); environment swaps replace
    /// the root under it (§7b). Set by ImmersiveView once the scene builds.
    var sceneContainer: Entity?

    /// The §7b whiteout overlay entity; the jump flashes it to mask the swap. Set by ImmersiveView.
    var whiteout: Entity?

    /// The two toggleable environments, both mounted under the container so switching is just
    /// a visibility flip (no rebuild — see EnvironmentSource). Set by ImmersiveView.
    var generatedRoot: Entity?    // the SceneBuilder "UniverseRoot" (L1–L4)
    var importedRoot: Entity?     // the Apple Spatial image environment

    /// Show exactly one environment per `environmentSource`. Safe to call before `importedRoot`
    /// finishes its async load — it just no-ops on the nil side.
    func applyEnvironmentVisibility() {
        generatedRoot?.isEnabled = (environmentSource == .generated)
        importedRoot?.isEnabled  = (environmentSource == .importedSpatial)
    }

    /// Flip between the imported Apple Spatial image and the generated scene (A/B comparison).
    func toggleEnvironmentSource() {
        environmentSource = (environmentSource == .generated) ? .importedSpatial : .generated
        applyEnvironmentVisibility()
    }

    /// Advance to the next bundled Apple Spatial sky and swap it into the imported container.
    func advanceImportedImage() {
        guard let importedRoot else { return }
        importedIndex = (importedIndex + 1) % SpatialImageEnvironment.resourceNames.count
        Task { @MainActor in await SpatialImageEnvironment.load(index: importedIndex, into: importedRoot) }
    }

    /// Jump to a fresh environment (§7b): flash the whiteout, and swap under the peak of the
    /// flash so the change is masked. A stepping stone to the full streak sequence.
    func newEnvironment() {
        // "New Environment" acts on whatever you're looking at: cycle the imported skies, or
        // jump the generated universe.
        if environmentSource == .importedSpatial { advanceImportedImage(); return }
        guard let whiteout, sceneContainer != nil else { return }
        // Don't retrigger while a flash is already running.
        if whiteout.components[WhiteoutComponent.self]?.active == true { return }
        var c = whiteout.components[WhiteoutComponent.self] ?? WhiteoutComponent()
        c.active = true; c.elapsed = 0
        whiteout.components.set(c)

        // Swap at peak white (single-await Task — the reliable pattern). ~fadeIn + a bit.
        Task { @MainActor in
            try? await Task.sleep(for: .seconds(0.30))
            applyNewEnvironment()
        }
    }

    /// LIGHT in-place swap: full-scene rebuilds (~6k star entities) crashed the device render
    /// server, so keep the star field and only re-orient the backdrop + rebuild the
    /// (few-hundred-entity) nebula. Deterministic seed chain reproduces (§7e).
    private func applyNewEnvironment() {
        guard let container = sceneContainer,
              let root = container.children.first(where: { $0.name == "UniverseRoot" }) else { return }
        let nextSeed = currentConfig.seed &* 2862933555777941757 &+ 3037000493
        var newConfig = EnvironmentConfig.random(seed: nextSeed)

        // Cycle backdrops through a shuffle-bag so New Environment visits EVERY panorama
        // before any repeats — independent random draws (even unbiased) clustered on a few
        // skies. Overrides the seed-derived backdrop; density is re-derived for the pick so
        // the §7a busyness suppression still applies.
        var pick = SeededRandom(seed: nextSeed ^ 0x424B_4452_5348_4646)   // "BKDRSHFF"
        newConfig.backdrop = nextBackdrop(rng: &pick)
        newConfig.nebulaDensity = pick.unit() * FarBackdrop.nebulaScale(forBackdrop: newConfig.backdrop)

        currentConfig = newConfig
        let gen = EnvironmentGenerator(config: newConfig)

        // Backdrop: reskin in place — new panorama (config.backdrop) + orientation + tint.
        // Loads ONE 8K texture (light — not a full-scene rebuild), hidden by the whiteout.
        if let backdrop = root.findEntity(named: "L1_Backdrop") as? ModelEntity {
            FarBackdrop.reskin(backdrop, gen: gen)
        }

        // Nebula: rebuild just this layer (keep the heavy star field untouched).
        root.children.filter { $0.name.hasPrefix("L2_Nebula") }.forEach { $0.removeFromParent() }
        root.addChild(NebulaVolume.make(gen: gen))
    }

    /// Shuffle-bag over the backdrops: hand out each panorama once (in a seeded random
    /// order) before refilling, so New Environment cycles through ALL of them. Refill avoids
    /// opening on the sky we just showed, so there are no back-to-back repeats across bags.
    private var backdropBag: [Int] = []
    private func nextBackdrop(rng: inout SeededRandom) -> Int {
        let count = FarBackdrop.textureNames.count
        if backdropBag.isEmpty {
            var bag = Array(0..<count)
            for i in stride(from: count - 1, through: 1, by: -1) {      // Fisher–Yates
                let j = Int(rng.next() % UInt64(i + 1))
                bag.swapAt(i, j)
            }
            // removeLast() serves the pick, so keep bag.last (the next pick) off the current sky.
            if count > 1 && bag.last == currentConfig.backdrop { bag.swapAt(0, count - 1) }
            backdropBag = bag
        }
        return backdropBag.removeLast()
    }
}

/// Minimal launcher; the real experience is the immersive space.
struct LauncherView: View {
    @Environment(AppModel.self) private var model
    @Environment(\.openImmersiveSpace) private var openImmersiveSpace
    @Environment(\.openWindow) private var openWindow

    var body: some View {
        VStack(spacing: 16) {
            Text("Float").font(.extraLargeTitle)
            Text("Step into deep space.").foregroundStyle(.secondary)
            Button("Enter") {
                Task {
                    model.immersion = .opening
                    _ = await openImmersiveSpace(id: AppModel.immersiveSpaceID)
                    model.immersion = .open
                }
            }
            .buttonStyle(.borderedProminent)

            // TEMP trigger for the environment jump until the two-hand pinch-spread gesture
            // lands (see float-reveal-gesture). Only meaningful once you're in the space.
            Button("New Environment") { model.newEnvironment() }
                .buttonStyle(.bordered)
                .disabled(model.immersion != .open)

            // A/B toggle: imported Apple Spatial image  ⇄  generated scene.
            Button(model.environmentSource == .generated ? "Show Imported Image" : "Show Generated Scene") {
                model.toggleEnvironmentSource()
            }
            .buttonStyle(.bordered)
            .disabled(model.immersion != .open)

            // Reading panel (read.amazon.com — Kindle Cloud Reader) as its own movable window.
            // Openable any time (even before entering) so you can sign in with your phone reachable,
            // then enter — the window and its session carry into the immersive space.
            Button("Read (Kindle)") { openWindow(id: "reader") }
                .buttonStyle(.bordered)
        }
        .padding(40)
    }
}

import RealityKit
import UIKit
import simd
import Metal   // MTLAttributeFormat for GaussianSplatResource buffer descriptors (§10)

// L1 — §4. Inward sphere, unlit hi-res equirectangular. Effectively at infinity.
enum FarBackdrop {
    // Base equirect panoramas in the bundle — NASA SVS Deep Star Maps (public domain) plus
    // Shutterstock RF space skies (see CREDITS.md). config.backdrop picks the base; per-seed
    // rotation + a subtle color wash vary it further so jumps rarely repeat the same sky (§7a).
    static let textureNames = [
        "deep_star_map_8k", "dual_nebula", "blue_filaments", "teal_orange", "dark_dust", "pale_haze"
    ]

    // §7a — how much real nebulosity/structure each panorama already carries (0 = near-black
    // star field, 1 = nebula-filled sky). MEASURED from the panoramas (blurred-luminance mean
    // + large-scale variation + non-black coverage), not eyeballed. Index-aligned with
    // textureNames. Drives generated-nebula density down (below) so our procedural gas doesn't
    // pile onto — and thereby give away — an already-busy real sky.
    static let busyness: [Float] = [0.00, 0.80, 0.89, 0.65, 0.28, 0.93]

    // Multiplier applied to a config's nebula density for a given backdrop: a quiet sky keeps
    // the full range, a busy sky gets a whisper. The freed-up depth cue is the (unchanged,
    // dense) L3 star field showing through more clearly — see AppModel.applyNewEnvironment.
    static func nebulaScale(forBackdrop index: Int) -> Float {
        let n = textureNames.count
        let b = busyness[((index % n) + n) % n]
        return 1.0 - 0.85 * b            // busy=0 → 1.0, busy=0.93 → ~0.21
    }

    @MainActor
    static func make(gen: EnvironmentGenerator) -> Entity {
        let mesh = MeshResource.generateSphere(radius: 1000)
        var material = UnlitMaterial()
        material.color = .init(tint: .init(white: 0.01, alpha: 1.0), texture: nil)  // near-black void until the texture loads
        let e = ModelEntity(mesh: mesh, materials: [material])
        e.name = "L1_Backdrop"
        e.scale.z = -1  // flip winding so the inside surface renders
        reskin(e, gen: gen)
        return e
    }

    // Pick the panorama, orientation, and tint for this environment and apply them to an
    // existing backdrop sphere — used both at build time and on a jump (§7b). Loads on
    // demand (no cache): replacing the material drops the old texture, so only ~1 8K
    // panorama is resident at a time (6 cached would blow the GPU budget).
    @MainActor
    static func reskin(_ e: ModelEntity, gen: EnvironmentGenerator) {
        var rng = gen.backdropStream()
        let idx = ((gen.config.backdrop % textureNames.count) + textureNames.count) % textureNames.count
        let name = textureNames[idx]

        // Per-seed orientation: uniform-random rotation so the sky lands differently.
        let pi = Float.pi
        let u1 = rng.unit(), u2 = rng.unit(), u3 = rng.unit()
        e.orientation = simd_quatf(vector: SIMD4<Float>(
            sqrt(1 - u1) * sin(2 * pi * u2), sqrt(1 - u1) * cos(2 * pi * u2),
            sqrt(u1) * sin(2 * pi * u3),     sqrt(u1) * cos(2 * pi * u3)))

        // Subtle per-seed color wash (mostly white, slight cast).
        let tint = UIColor(red: CGFloat(0.82 + 0.18 * rng.unit()),
                           green: CGFloat(0.82 + 0.18 * rng.unit()),
                           blue: CGFloat(0.82 + 0.18 * rng.unit()), alpha: 1)

        Task { @MainActor in
            guard let tex = try? await TextureResource(named: name) else {
                print("[Float] L1 backdrop texture '\(name)' not found")
                return
            }
            var lit = UnlitMaterial()
            lit.color = .init(tint: tint, texture: .init(tex))
            e.model?.materials = [lit]
        }
    }
}

// §7b whiteout — a brief full-view white flash that masks the environment swap. Driven by
// a System (runs every render frame, unlike the Task tweens that proved unreliable here).
struct WhiteoutComponent: Component {
    var active = false
    var elapsed: TimeInterval = 0
    var fadeIn: TimeInterval = 0.25
    var hold: TimeInterval = 0.12
    var fadeOut: TimeInterval = 0.45
    var total: TimeInterval { fadeIn + hold + fadeOut }
}

struct WhiteoutSystem: System {
    static let query = EntityQuery(where: .has(WhiteoutComponent.self))
    init(scene: Scene) {}
    func update(context: SceneUpdateContext) {
        MainActor.assumeIsolated {
            for e in context.entities(matching: Self.query, updatingSystemWhen: .rendering) {
                guard var c = e.components[WhiteoutComponent.self], c.active,
                      let me = e as? ModelEntity else { continue }
                c.elapsed += context.deltaTime
                var a: Float
                if c.elapsed < c.fadeIn {
                    a = Float(c.elapsed / c.fadeIn)                                   // fade to white
                } else if c.elapsed < c.fadeIn + c.hold {
                    a = 1                                                            // peak (swap happens here)
                } else if c.elapsed < c.total {
                    a = Float(1 - (c.elapsed - c.fadeIn - c.hold) / c.fadeOut)         // reveal new env
                } else {
                    a = 0; c.active = false
                }
                a = max(0, min(1, a))
                var mat = UnlitMaterial()
                mat.color = .init(tint: UIColor(white: 1, alpha: CGFloat(a)), texture: nil)
                mat.blending = .transparent(opacity: 1.0)

