input.new_string:
var rng = gen.backdropStream()
let pano = panorama(at: gen.config.backdrop)
let name = pano.name

let pi = Float.pi
if pano.grounded {
    // YAW ONLY. A uniform-random rotation would tilt (or invert) the horizon, and a
    // tilted horizon is worse than no horizon at all — it supplies a confident
    // "which way is up" cue that contradicts the vestibular system. That is the
    // exact failure a grounded sky exists to prevent, so keep the ground level and
    // vary only the compass heading (§9).
    e.orientation = simd_quatf(angle: 2 * pi * rng.unit(), axis: [0, 1, 0])
} else {
    // Per-seed orientation: uniform-random rotation so the sky lands differently.
    let u1 = rng.unit(), u2 = rng.unit(), u3 = rng.unit()
    e.orientation = simd_quatf(vector: SIMD4<Float>(
        sqrt(1 - u1) * sin(2 * pi * u2), sqrt(1 - u1) * cos(2 * pi * u2),
        sqrt(u1) * sin(2 * pi * u3),     sqrt(u1) * cos(2 * pi * u3)))
}

