import struct
def boxes(data, start, end, depth=0):
    p=start
    while p+8<=end:
        size=struct.unpack('>I',data[p:p+4])[0]; typ=data[p+4:p+8]
        hdr=8
        if size==1:
            size=struct.unpack('>Q',data[p+8:p+16])[0]; hdr=16
        elif size==0:
            size=end-p
        try: ts=typ.decode('ascii')
        except: ts=repr(typ)
        if 32<=data[p+4]<127:
            print('  '*depth+f"{ts} ({size})")
        # recurse into container boxes
        if ts in ('meta','iprp','ipco','grpl','iinf','iref','dinf','moov','trak'):
            inner=p+hdr
            if ts=='meta': inner=p+hdr+4  # meta has version/flags
            boxes(data,inner,p+size,depth+1)
        # print group boxes of interest
        if ts in ('ster','grpl'):
            print('  '*depth+f"   >>> {ts} FOUND")
        p+=size
        if size==0: break
