import RealityKit

/// Assembles the layered depth scene (§3) from an EnvironmentConfig (§7a).
/// Every layer is a child of one stationary root at the origin (§9: camera never moves).
enum SceneBuilder {
    @MainActor
    static func build(config: EnvironmentConfig, clock: AnimationClock) -> Entity {
        print("[Float] SceneBuilder.build — nebula:\(config.nebulaBackend) comets:\(PhenomenaSpawner.cometCount) meteors:\(PhenomenaSpawner.meteorCount)")
        let root = Entity()
        root.name = "UniverseRoot"
        root.components.set(ClockComponent(clock: clock))  // §5 shared clock handle for ECS systems

        let gen = EnvironmentGenerator(config: config)

        root.addChild(FarBackdrop.make(gen: gen))       // L1 §4
        root.addChild(NebulaVolume.make(gen: gen))      // L2 nebula (splat / particle fallback)
        root.addChild(StarVolume.make(gen: gen))        // L3 — the depth workhorse
        root.addChild(PhenomenaSpawner.make(gen: gen))  // L4 §6

        if let body = config.body {
            root.addChild(CelestialBodies.make(body, gen: gen))          // §7c
        }
        if let field = config.asteroidField {
            root.addChild(AsteroidField.make(field, gen: gen))           // §7d
        }
        return root
    }
}

import SwiftUI
import RealityKit
import ARKit

/// Hosts the RealityKit scene and wires input providers.
/// Spec: §3 layered scene, §7 hand tracking, §7f flick.
struct ImmersiveView: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        RealityView { content, attachments in
            // Register ECS components and systems once.
            ClockComponent.registerComponent()
            StarVolumeComponent.registerComponent()
            StarComponent.registerComponent()
            PhenomenonComponent.registerComponent()
            WhiteoutComponent.registerComponent()
            AnimationClockSystem.registerSystem()
            StarAnimationSystem.registerSystem()
            PhenomenaSystem.registerSystem()
            AsteroidImpactSystem.registerSystem()
            WhiteoutSystem.registerSystem()

            // Persistent container holds the universe root; environment swaps (§7b) add a
            // new "UniverseRoot" and crossfade out the old one, all under this container.
            let container = Entity()
            container.name = "SceneContainer"
            let generated = SceneBuilder.build(config: model.currentConfig, clock: model.clock)
            container.addChild(generated)
            content.add(container)
            model.sceneContainer = container
            model.generatedRoot = generated

            // Imported Apple Spatial environment — an empty container mounted now (so toggling
            // works immediately) whose skybox loads async and can be cycled (importedIndex).
            let imported = SpatialImageEnvironment.makeContainer()
            container.addChild(imported)
            model.importedRoot = imported
            model.applyEnvironmentVisibility()   // apply launch default (hides generated if imported)
            Task { @MainActor in
                await SpatialImageEnvironment.load(index: model.importedIndex, into: imported)
            }

            // §7b whiteout overlay — a persistent inward white sphere (alpha 0) the jump flashes.
            let whiteout = WhiteoutSystem.makeEntity()
            container.addChild(whiteout)
            model.whiteout = whiteout

            // Attach the (hidden) control panel to the container so it survives swaps;
            // revealed by the two-hand pinch-spread gesture (§7, float-reveal-gesture).
            if let panel = attachments.entity(for: "controlPanel") {
                panel.isEnabled = false
                container.addChild(panel)
            }
        } update: { _, _ in
            // Environment swaps are driven imperatively via AppModel.newEnvironment()
            // (it mutates the container directly), so nothing to reconcile here.
        } attachments: {
            Attachment(id: "controlPanel") {
                ControlPanelView().environment(model)
            }
        }
        .task { await runHandTracking() }   // §7 double-pinch, §7f flick
        .upperLimbVisibility(.visible)      // keep hands visible for flicking
    }

    /// ARKit hand-tracking loop (90 Hz on v26+). Feeds the gesture detectors.
    private func runHandTracking() async {
        // TODO: start ARKitSession + HandTrackingProvider; route joints to
        //       DoublePinchDetector (§7) and FlickInteraction (§7f).
    }
}

